CREATE INDEX board_watches_board ON board_watches(board_id,user_id);
CREATE INDEX notifications_user ON notifications(user_id,id DESC);
CREATE TRIGGER activity_notifications AFTER INSERT ON activity BEGIN INSERT OR IGNORE INTO notifications(user_id,activity_id) SELECT DISTINCT u.id,NEW.id FROM users u JOIN boards b ON b.id=NEW.board_id WHERE u.active=1 AND u.id<>NEW.actor_id AND b.deleted_at IS NULL AND (u.role='admin' OR EXISTS(SELECT 1 FROM board_members m WHERE m.board_id=NEW.board_id AND m.user_id=u.id)) AND (EXISTS(SELECT 1 FROM board_watches w WHERE w.user_id=u.id AND w.board_id=NEW.board_id) OR (NEW.entity_type='cards' AND EXISTS(SELECT 1 FROM card_watches w WHERE w.user_id=u.id AND w.card_id=NEW.entity_id)));END;
CREATE INDEX attachments_card ON attachments(card_id,id);
CREATE UNIQUE INDEX sessions_public ON sessions(public_id);
CREATE TRIGGER session_public_id AFTER INSERT ON sessions WHEN NEW.public_id='' BEGIN UPDATE sessions SET public_id=lower(hex(randomblob(16))) WHERE token_hash=NEW.token_hash;END;
