CREATE INDEX reviews_requester ON reviews(requester_id,id DESC);
CREATE INDEX review_members_user ON review_members(user_id,review_id);
CREATE INDEX review_events_review ON review_events(review_id,id DESC);
CREATE TRIGGER review_membership_removed AFTER DELETE ON board_members BEGIN UPDATE reviews SET version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id IN(SELECT m.review_id FROM review_members m JOIN reviews r ON r.id=m.review_id JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id WHERE m.user_id=OLD.user_id AND c.board_id=OLD.board_id);INSERT INTO review_events(review_id,actor,subject_id,action,note) SELECT m.review_id,'Sistema',OLD.user_id,'review_eligibility_changed','Membro rimosso dalla bacheca; i suoi voti sono invalidati.' FROM review_members m JOIN reviews r ON r.id=m.review_id JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id WHERE m.user_id=OLD.user_id AND c.board_id=OLD.board_id AND (SELECT count(*) FROM review_events e WHERE e.review_id=m.review_id)<10000;DELETE FROM review_votes WHERE user_id=OLD.user_id AND review_id IN(SELECT r.id FROM reviews r JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id WHERE c.board_id=OLD.board_id);END;
CREATE TRIGGER review_membership_role AFTER UPDATE OF role ON board_members WHEN NEW.role<>OLD.role BEGIN UPDATE reviews SET version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id IN(SELECT m.review_id FROM review_members m JOIN reviews r ON r.id=m.review_id JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id WHERE m.user_id=NEW.user_id AND c.board_id=NEW.board_id);INSERT INTO review_events(review_id,actor,subject_id,action,note) SELECT m.review_id,'Sistema',NEW.user_id,'review_eligibility_changed','Ruolo del membro modificato.' FROM review_members m JOIN reviews r ON r.id=m.review_id JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id WHERE m.user_id=NEW.user_id AND c.board_id=NEW.board_id AND (SELECT count(*) FROM review_events e WHERE e.review_id=m.review_id)<10000;DELETE FROM review_votes WHERE user_id=NEW.user_id AND NEW.role='observer' AND review_id IN(SELECT r.id FROM reviews r JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id WHERE c.board_id=NEW.board_id);END;
CREATE TRIGGER review_user_eligibility AFTER UPDATE OF active,role ON users WHEN NEW.active<>OLD.active OR NEW.role<>OLD.role BEGIN UPDATE reviews SET version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id IN(SELECT review_id FROM review_members WHERE user_id=NEW.id);INSERT INTO review_events(review_id,actor,subject_id,action,note) SELECT review_id,'Sistema',NEW.id,'review_eligibility_changed','Stato o ruolo globale del revisore modificato.' FROM review_members m WHERE user_id=NEW.id AND (SELECT count(*) FROM review_events e WHERE e.review_id=m.review_id)<10000;DELETE FROM review_votes WHERE user_id=NEW.id AND (NEW.active=0 OR NEW.role='observer');END;
CREATE VIEW review_eligibility AS SELECT m.review_id,m.user_id,CASE WHEN u.active=1 AND u.role<>'observer' AND bm.role IS NOT NULL AND bm.role<>'observer' AND m.user_id<>r.requester_id THEN 1 ELSE 0 END eligible FROM review_members m JOIN reviews r ON r.id=m.review_id JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id JOIN users u ON u.id=m.user_id LEFT JOIN board_members bm ON bm.board_id=c.board_id AND bm.user_id=m.user_id;
CREATE VIEW review_resolved AS SELECT a.*,CASE WHEN due_date<>'' AND due_date<date('now') AND status IN('pending','changes_requested') THEN 1 ELSE 0 END overdue FROM(SELECT r.*,c.board_id,k.title card_title,u.name requester,(SELECT count(*) FROM review_members m WHERE m.review_id=r.id) reviewer_count,(SELECT count(*) FROM review_votes v JOIN review_eligibility e ON e.review_id=v.review_id AND e.user_id=v.user_id WHERE v.review_id=r.id AND e.eligible=1 AND v.decision='approved') approved_count,(SELECT count(*) FROM review_votes v JOIN review_eligibility e ON e.review_id=v.review_id AND e.user_id=v.user_id WHERE v.review_id=r.id AND e.eligible=1 AND v.decision='changes_requested') changes_count,CASE WHEN r.cancelled_at IS NOT NULL THEN 'cancelled' WHEN EXISTS(SELECT 1 FROM review_votes v JOIN review_eligibility e ON e.review_id=v.review_id AND e.user_id=v.user_id WHERE v.review_id=r.id AND e.eligible=1 AND v.decision='changes_requested') THEN 'changes_requested' WHEN EXISTS(SELECT 1 FROM review_votes v JOIN review_eligibility e ON e.review_id=v.review_id AND e.user_id=v.user_id WHERE v.review_id=r.id AND e.eligible=1 AND v.decision='approved') AND(r.policy='any' OR (SELECT count(*) FROM review_votes v JOIN review_eligibility e ON e.review_id=v.review_id AND e.user_id=v.user_id WHERE v.review_id=r.id AND e.eligible=1 AND v.decision='approved')=(SELECT count(*) FROM review_members m WHERE m.review_id=r.id)) THEN 'approved' ELSE 'pending' END status FROM reviews r JOIN cards k ON k.id=r.card_id JOIN columns c ON c.id=k.column_id JOIN users u ON u.id=r.requester_id)a;
CREATE INDEX reports_owner ON saved_reports(user_id,pinned DESC,id DESC);
CREATE VIEW ob_card_objects AS SELECT k.*,json_object('id',k.id,'column_id',k.column_id,'title',k.title,'description',k.description,'label',k.label,'labels',json(k.labels),'due_date',k.due_date,'assignee',k.assignee,'cover',k.cover,'position',k.position,'completed',json(CASE k.completed WHEN 1 THEN 'true' ELSE 'false' END),'checklist',json(k.checklist),'priority',k.priority,'estimate_minutes',k.estimate_minutes,'archived',json(CASE k.archived WHEN 1 THEN 'true' ELSE 'false' END),'version',k.version,'created_at',k.created_at,'updated_at',k.updated_at,'start_date',k.start_date,'blocked_reason',k.blocked_reason,'actual_minutes',k.actual_minutes,'reference_url',k.reference_url,'assignee_ids',json((SELECT json_group_array(user_id) FROM card_assignees WHERE card_id=k.id)),'assignees',json((SELECT json_group_array(json_object('id',u.id,'name',u.name,'username',u.username)) FROM card_assignees a JOIN users u ON u.id=a.user_id WHERE a.card_id=k.id)),'custom_values',json(k.custom_values),'milestone_key',k.milestone_key,'logged_minutes',coalesce((SELECT sum(minutes) FROM worklogs WHERE card_id=k.id AND deleted_at IS NULL),0),'total_minutes',k.actual_minutes+coalesce((SELECT sum(minutes) FROM worklogs WHERE card_id=k.id AND deleted_at IS NULL),0)) data,json_object('id',k.id,'column_id',k.column_id,'title',k.title,'description_preview',substr(k.description,1,160),'checklist_total',json_array_length(k.checklist),'checklist_done',(SELECT count(*) FROM json_each(k.checklist) WHERE json_extract(value,'$.done')=1),'label',k.label,'labels',json(k.labels),'due_date',k.due_date,'assignee',k.assignee,'cover',k.cover,'position',k.position,'completed',json(CASE k.completed WHEN 1 THEN 'true' ELSE 'false' END),'priority',k.priority,'estimate_minutes',k.estimate_minutes,'archived',json(CASE k.archived WHEN 1 THEN 'true' ELSE 'false' END),'version',k.version,'created_at',k.created_at,'updated_at',k.updated_at,'start_date',k.start_date,'blocked_reason',k.blocked_reason,'actual_minutes',k.actual_minutes,'reference_url',k.reference_url,'assignee_ids',json((SELECT json_group_array(user_id) FROM card_assignees WHERE card_id=k.id)),'assignees',json((SELECT json_group_array(json_object('id',u.id,'name',u.name,'username',u.username)) FROM card_assignees a JOIN users u ON u.id=a.user_id WHERE a.card_id=k.id)),'custom_values',json(k.custom_values),'milestone_key',k.milestone_key,'logged_minutes',coalesce((SELECT sum(minutes) FROM worklogs WHERE card_id=k.id AND deleted_at IS NULL),0),'total_minutes',k.actual_minutes+coalesce((SELECT sum(minutes) FROM worklogs WHERE card_id=k.id AND deleted_at IS NULL),0)) summary FROM cards k;
CREATE VIEW ob_board_objects AS SELECT b.*,json_object('id',b.id,'name',b.name,'description',b.description,'guidelines',b.guidelines,'custom_fields',json((SELECT json_group_array(json_object('id',id,'key',key,'name',name,'type',type,'options',json(options),'position',position,'deleted_at',deleted_at)) FROM (SELECT * FROM custom_fields WHERE board_id=b.id ORDER BY position,id))),'milestones',json((SELECT json_group_array(json_object('id',id,'key',key,'title',title,'due_date',due_date,'completed',json(CASE completed WHEN 1 THEN 'true' ELSE 'false' END),'deleted_at',deleted_at)) FROM milestones WHERE board_id=b.id)),'color',b.color,'starred',json(CASE ob_starred(b.id,b.starred) WHEN 1 THEN 'true' ELSE 'false' END),'archived',json(CASE b.archived WHEN 1 THEN 'true' ELSE 'false' END),'version',b.version,'created_at',b.created_at,'updated_at',b.updated_at,'role',ob_role(b.id),'membership_role',ob_role(b.id),'readonly',json(CASE ob_readonly(b.id) WHEN 1 THEN 'true' ELSE 'false' END),'columns',json((SELECT json_group_array(json(col)) FROM(SELECT json_object('id',c.id,'title',c.title,'position',c.position,'wip_limit',c.wip_limit,'version',c.version,'created_at',c.created_at,'updated_at',c.updated_at,'cards',json((SELECT json_group_array(json(item)) FROM(SELECT CASE ob_summary() WHEN 1 THEN k.summary ELSE k.data END item FROM ob_card_objects k WHERE k.column_id=c.id AND k.deleted_at IS NULL AND (ob_archived() OR k.archived=0) ORDER BY k.position,k.id)))) col FROM columns c WHERE c.board_id=b.id AND c.deleted_at IS NULL ORDER BY c.position,c.id)))) data FROM boards b;
